{
  "op": "aggregate",
  "collection": "personer",
  "pipeline": [
    {
      "$match": {
        "selskapOrgNr": {
          "$exists": true,
          "$ne": null
        },
        "selskapRolle": {
          "$exists": true,
          "$ne": null
        }
      }
    },
    {
      "$lookup": {
        "from": "politikere",
        "let": {
          "pname": "$navn",
          "pfd": "$fødselsdato",
          "pyear": "$fødselsår"
        },
        "pipeline": [
          {
            "$match": {
              "$expr": {
                "$and": [
                  { "$eq": ["$navn", "$$pname"] },
                  {
                    "$or": [
                      {
                        "$and": [
                          { "$ne": ["$$pfd", null] },
                          { "$eq": ["$fødselsdato", "$$pfd"] }
                        ]
                      },
                      {
                        "$and": [
                          { "$ne": ["$$pyear", null] },
                          { "$eq": ["$fødselsår", "$$pyear"] }
                        ]
                      },
                      {
                        "$and": [
                          { "$eq": ["$$pfd", null] },
                          { "$eq": ["$$pyear", null] }
                        ]
                      }
                    ]
                  }
                ]
              }
            }
          }
        ],
        "as": "politikereMatch"
      }
    },
    {
      "$match": {
        "politikereMatch.0": {
          "$exists": true
        }
      }
    },
    {
      "$group": {
        "_id": {
          "orgNr": "$selskapOrgNr",
          "navn": "$selskapNavn"
        },
        "antall": {
          "$sum": 1
        }
      }
    },
    {
      "$project": {
        "_id": 0,
        "selskapsnavn": "$_id.navn",
        "organisasjonsnummer": "$_id.orgNr",
        "antall_politikerroller": "$antall"
      }
    }
  ]
}
